async function getPdfTitleAndDownload(blob){const url=URL.createObjectURL(blob);const loadingTask=pdfjsLib.getDocument(url);const pdf=await loadingTask.promise;const metadata=await pdf.getMetadata();let title=metadata.info.Title||"DefaultFileName";title=title.replace(/[\/:*?"<>|]/g,"")+".pdf";let a=document.createElement("a");a.href=url;a.download=title;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url)}